import * as React from "react";
import { cx } from "./cx";

export interface AspectRatioProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Width over height, e.g. 16 / 9. */
  ratio?: number;
}

export function AspectRatio({ ratio = 16 / 9, style, className, ...props }: AspectRatioProps) {
  return <div className={cx("rs-ratio", className)} style={{ aspectRatio: ratio, ...style }} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Aspect ratio: a box that keeps its proportions ── */
.rs-ratio{position:relative;width:100%;overflow:hidden;border-radius:var(--radius)}
.rs-ratio>*{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
